// NOTE: Assertions have been autogenerated by chore/litgen UTC_ARGS: --function=(?:\Qmain.init\E|\Qmain.main\E) --check-globals=smart
// NOTE: Autogenerated snapshot targets: DARWIN-ARM64 LINUX-AMD64
package main

import (
	"unsafe"

	"github.com/goplus/lib/c"
	"github.com/goplus/lib/py"
	"github.com/goplus/lib/py/math"
	"github.com/goplus/lib/py/std"
)

// CHECK: {{^}}@[[GLOB0:[0-9]+]] = private unnamed_addr constant [5 x i8] c"world", align 1{{$}}
// CHECK: {{^}}@[[GLOB1:[0-9]+]] = private unnamed_addr constant [5 x i8] c"hello", align 1{{$}}
// CHECK: {{^}}@[[GLOB2:[0-9]+]] = private unnamed_addr constant [3 x i8] c"pi\00", align 1{{$}}
// CHECK: {{^}}@[[GLOB3:[0-9]+]] = private unnamed_addr constant [14 x i8] c"lens = %d %d\0A\00", align 1{{$}}
// CHECK: {{^}}@[[GLOB4:[0-9]+]] = private unnamed_addr constant [14 x i8] c"ptrs = %d %d\0A\00", align 1{{$}}
// CHECK: {{^}}@[[GLOB5:[0-9]+]] = private unnamed_addr constant [12 x i8] c"pi = %.15g\0A\00", align 1{{$}}
// CHECK: {{^}}@[[GLOB6:[0-9]+]] = private unnamed_addr constant [4 x i8] c"abs\00", align 1{{$}}
// CHECK: {{^}}@[[GLOB7:[0-9]+]] = private unnamed_addr constant [6 x i8] c"print\00", align 1{{$}}

func main() {
	v := 100
	x := py.List(true, false, 1, float32(2.1), 3.1, uint(4), 1+2i, complex64(3+4i),
		"hello", []byte("world"), [...]byte{1, 2, 3}, [...]byte{}, &v, unsafe.Pointer(&v))
	y := py.List(std.Abs, std.Print, math.Pi)
	c.Printf(c.Str("lens = %d %d\n"), x.ListLen(), y.ListLen())
	c.Printf(c.Str("ptrs = %d %d\n"), x.ListItem(12).IsTrue(), x.ListItem(13).IsTrue())
	c.Printf(c.Str("pi = %.15g\n"), y.ListItem(2).Float64())
}

